const $=s=>document.querySelector(s), results=$('#results'),input=$('#word');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const norm=s=>s.toLowerCase().replaceAll('ё','е').normalize('NFD').replace(/[\u0300\u0301]/g,'').normalize('NFC').trim();
const shard=s=>[...norm(s)].slice(0,2).map(c=>c.codePointAt(0).toString(16)).join('-')||'5f';
const cache=new Map();
async function data(kind,s){const key=kind+'-'+shard(s);if(!cache.has(key))cache.set(key,(async()=>{let r=await fetch('data/'+key+'.bin');if(r.status===404)return {};if(!r.ok)throw Error('Не удалось загрузить словарь');if(!('DecompressionStream' in window))throw Error('Ваш браузер не поддерживает сжатые данные словаря. Попробуйте современную версию браузера.');let stream=r.body.pipeThrough(new DecompressionStream('gzip'));return JSON.parse(await new Response(stream).text())})());return cache.get(key)}
const flatten=x=>Array.isArray(x)?x.flatMap(flatten):x&&typeof x==='object'?[x]:[];
function split(s){let a=[],level=0,start=0;for(let i=0;i<s.length;i++){if(s[i]==='('||s[i]==='[')level++;if(s[i]===')'||s[i]===']')level--;if(s[i]===','&&level===0){a.push(s.slice(start,i));start=i+1}}a.push(s.slice(start));return a}
const pos={'с':'существительное','п':'прилагательное','г':'глагол','мс':'местоимение','мс-п':'местоименное прилагательное','числ':'числительное','числ-п':'счётное прилагательное','н':'наречие','предл':'предлог','союз':'союз','част':'частица','межд':'междометие','предик':'предикатив','вводн':'вводное слово','сравн':'сравнительная степень'};
const cases=['Именительный','Родительный','Дательный','Винительный','Творительный','Предложный'];
const adjCases=['Именительный','Родительный','Дательный','Винительный · неодуш.','Винительный · одуш.','Творительный','Предложный'];
function adjLabel(i){if(i<28){let group=Math.floor(i/7);return adjCases[i%7]+' · '+['муж. род','жен. род','ср. род','мн. число'][group]}return ['Краткая форма · муж. род','Краткая форма · жен. род','Краткая форма · ср. род','Краткая форма · мн. число','Сравнительная степень'][i-28]||'Форма '+(i+1)}
function label(t,i){if(t==='с')return cases[i%6]+' · '+(i<6?'ед. число':'мн. число');if(t==='п')return adjLabel(i);if(t==='мс-п'||t==='числ-п')return adjLabel(i);if(t==='мс')return cases[i]||'Форма '+(i+1);if(t==='числ')return ['Именительный','Родительный','Дательный','Винительный · неодуш.','Винительный · одуш.','Творительный','Предложный'][i]||'Форма '+(i+1);if(t==='г'){let basic=['Инфинитив','Прошедшее · муж. род','Прошедшее · жен. род','Прошедшее · ср. род','Прошедшее · мн. число',...['1 л. ед.','2 л. ед.','3 л. ед.','1 л. мн.','2 л. мн.','3 л. мн.'].map(x=>'Настоящее · '+x),...['1 л. ед.','2 л. ед.','3 л. ед.','1 л. мн.','2 л. мн.','3 л. мн.'].map(x=>'Будущее · '+x),'Повелительное · ед. число','Повелительное · мн. число','Деепричастие · настоящее','Деепричастие · прошедшее'];if(i<basic.length)return basic[i];let n=i-basic.length;return ['Причастие действ. наст.','Причастие действ. прош.','Причастие страд. наст.','Причастие страд. прош.'][Math.floor(n/32)]+' · '+adjLabel(n%32)}return 'Форма '+(i+1)}
function makeForms(entry){if(!Object.hasOwn(entry,'п'))return null;let good=[],uncertain=[],absent=[],missingBase=false;String(entry['п']).split(';').forEach((cell,i)=>{let rowGood=[],rowUncertain=[],rowAbsent=[];for(let part of split(cell)){if(part==='-'){rowAbsent.push('Отсутствует в источнике');continue}let isAbsent=part.endsWith('-');let marker=part.endsWith('?')?'предположительно':part.endsWith('*')?'затруднительная':'';part=part.replace(/[?*\-]$/,'');let annotation=(part.match(/\([^)]*\)|\[[^\]]*\]/g)||[]).join(' ');part=part.replace(/\([^)]*\)|\[[^\]]*\]/g,'');let m=part.match(/^([1-5])/),key='о'+(m?m[1]:'');if(!Object.hasOwn(entry,key)){missingBase=true;continue}let form=String(entry[key]??'')+(m?part.slice(1):part);if(!form)continue;let value=form+(annotation?' '+annotation:'')+(isAbsent?' — Отсутствует в источнике':marker?' ('+marker+')':'');(isAbsent?rowAbsent:marker?rowUncertain:rowGood).push(value)}if(rowGood.length)good.push([label(entry.с?.т,i),rowGood.join(', ')]);if(rowUncertain.length)uncertain.push([label(entry.с?.т,i),rowUncertain.join(', ')]);if(rowAbsent.length)absent.push([label(entry.с?.т,i),rowAbsent.join(', ')])});return {good,uncertain,absent,missingBase}}
function rows(list){return '<div class="forms">'+list.map(([a,b])=>`<div class="form-row"><span class="label">${esc(a)}</span><span class="value">${esc(b)}</span></div>`).join('')+'</div>'}
const fieldNames={т:'часть речи',т2:'тип склонения',р:'род',рм:'морфологический род',о:'одушевлённость',и:'тип склонения или спряжения',у1:'основная схема ударения',у2:'дополнительная схема ударения',р2:'второй родительный падеж (Р2)',п2:'второй предложный падеж (П2)',п2ф:'факультативный второй предложный падеж (П2)',ч:'чередование беглой гласной с нулём (* в исходной записи)',чё:'чередование ё/е (Ё в исходной записи)',чо:'чередование о/е (о в исходной записи)',ч2:'особое чередование (** в исходной записи)',ч3:'указание для образования основы настоящего времени',гв:'вид глагола',гп:'переходность глагола',гмн:'многократный глагол',гбл:'безличный глагол',гпс:'суффикс страдательного причастия',ос:'номер отклонения от стандартного словоизменения',осф:'номер факультативного отклонения',до:'параграф дополнительных особенностей (# в исходной записи)',фз:'маска затруднительных форм',фн:'маска отсутствующих форм',фп:'маска предположительных форм',мн:'помета множественного числа',с2ч:'склонение обеих частей существительного',гпр:'сведения о глаголе противоположного вида ($ в исходной записи)',гпрс:'вычисленный глагол противоположного вида в данных источника',сб:'основа слова',фк:'факультативная часть индекса или вариант',фр:'особые формы во фразеологизмах (% в исходной записи)',слсч:'употребление в сочетаниях',з:'указание значения',з2:'дополнительное указание значения',з3:'сведения о вариантах слова'};
const fieldValues={т:pos,т2:{п:'адъективный',мс:'местоименный','мс-п':'местоименный',ч:'числительных'},р:{м:'мужской',ж:'женский',с:'средний',мж:'мужской и женский',мс:'мужской и средний',жс:'женский и средний',см:'средний и мужской',сж:'средний и женский',о:'общий'},рм:{ж:'женский',с:'средний'},о:{н:'неодушевлённое',о:'одушевлённое',но:'неодушевлённое и одушевлённое'},гв:{нсв:'несовершенный',св:'совершенный','св-нсв':'двувидовой'},гп:{нп:'непереходный',п:'переходный'},мн:{t:'слово употребляется во множественном числе',от:'форма множественного числа другого существительного'}};
function fieldDescription(k,v){const label=fieldNames[k]||'поле исходного словаря';const value=fieldValues[k]?.[String(v)];return label+(value?': '+value:'')}
function annotations(entry){let short=Object.entries(entry.с||{}),long=Object.entries(entry).filter(([k])=>k!=='с'&&k!=='п'&&!/^о[1-5]?$/.test(k));let all=[...short,...long];return all.length?`<div class="dictionary-meta"><div class="variant-title">Пометы и пояснения</div><div class="marks">${all.map(([k,v])=>`<span class="mark"><b>${esc(k)}: ${esc(typeof v==='object'?JSON.stringify(v):v)}</b> <span>(${esc(fieldDescription(k,v))})</span></span>`).join('')}</div></div>`:''}
function originalHints(line){let notes=[];let accent=line.match(/^\S+\s+([0-9][0-9.,]*)/);if(accent)notes.push(`${accent[1]} (положение ударения в заглавном слове; числа после запятой также указывают на букву ё)`);let basic=line.match(/^\S+\s+[0-9][0-9.,]*\s+(мо|жо|со|м|ж|с|п|нсв|св|нп|числ\.-п|числ|мс-п|мс|н|предл|союз|част|межд|предик|вводн)(?=[\s.,:;]|$)/);let names={м:'существительное мужского рода',ж:'существительное женского рода',с:'существительное среднего рода',мо:'существительное мужского рода, одушевлённое',жо:'существительное женского рода, одушевлённое',со:'существительное среднего рода, одушевлённое',п:'прилагательное',нсв:'глагол несовершенного вида',св:'глагол совершенного вида',нп:'непереходный глагол',числ:'числительное','числ.-п':'счётное прилагательное',мс:'местоимение-существительное','мс-п':'местоименное прилагательное',н:'наречие',предл:'предлог',союз:'союз',част:'частица',межд:'междометие',предик:'предикатив',вводн:'вводное слово'};if(basic)notes.push(`${basic[1]} (${names[basic[1]]})`);if(line.includes('**'))notes.push('** (подтип с особыми чередованиями)');else if(line.includes('*'))notes.push('* (подтип с чередованием беглой гласной с нулём)');if(line.includes('@'))notes.push('@ (морфологически нерегулярные формы)');if(line.includes('%'))notes.push('% (особые формы во фразеологизмах)');if(line.includes('$'))notes.push('$ (сведения о глаголе противоположного вида)');if(/#\d/.test(line))notes.push('# (ссылка на дополнительные особенности словоизменения)');if(/"\d+"/.test(line))notes.push('цифра в кавычках (номер отклонения от стандартного словоизменения)');if(line.includes('//'))notes.push('// (вариант наряду с указанным)');if(line.includes('['))notes.push('[ ] (факультативные сведения или варианты)');if(line.includes('_'))notes.push('_ _ (выделение пояснения или словарной пометы в исходном тексте)');if(line.includes('!'))notes.push('! (образование соответствующей формы затруднительно)');if(line.includes('?'))notes.push('? (отсутствует соответствующая форма)');if(line.includes('~'))notes.push('~ (сравнительной степени нет)');if(line.includes('=>')||line.includes('<='))notes.push('=> и <= (границы группы вариантов записи)');return notes}
function originalBlock(original){if(!original?.entries?.length)return `<div class="original"><div class="variant-title">Исходная словарная запись</div><p class="meta">Точная запись для этого слова в исходном текстовом файле не найдена.</p></div>`;return `<div class="original"><div class="variant-title">${original.related?'Связанная запись исходного словаря: '+esc(original.related):'Исходные словарные записи'}</div><p class="note">Обозначения и написание сохранены как в электронной версии словаря.</p>${original.entries.map(x=>`<div class="original-line">${esc(x)}</div>${originalHints(x).length?`<div class="original-hints">${originalHints(x).map(h=>`<span>${esc(h)}</span>`).join('')}</div>`:''}`).join('')}</div>`}
function card(lemma,obj,original){let entries=flatten(obj);return `<article class="card source-card"><h3>${esc(lemma)}</h3>${originalBlock(original)}</article>`+entries.map((e,i)=>{let p=e.с||{},info=[pos[p.т]||p.т,({'м':'мужской род','ж':'женский род','с':'средний род'}[p.р]||p.р),({'о':'одушевлённое','н':'неодушевлённое'}[p.о]||''),({'св':'совершенный вид','нсв':'несовершенный вид','св-нсв':'двувидовой'}[p.гв]||'')].filter(Boolean).join(' · ');let f=makeForms(e);let meaning=[e.з,e.з2,e.з3].filter(Boolean).join(' · ');return `<article class="card"><div class="card-head"><div><h3>${esc(lemma)}</h3><div class="meta">${esc(info)}${meaning?'<br>'+esc(meaning):''}</div></div>${entries.length>1?`<span class="badge">Вариант ${i+1} / ${entries.length}</span>`:''}</div>${annotations(e)}${f?`<div class="variant"><div class="variant-title">Словоформы</div>${f.good.length?rows(f.good):'<p class="meta">Достоверные формы в источнике не приведены.</p>'}${f.uncertain.length?`<div class="uncertain"><h4>Формы с оговорками</h4><div class="note">Согласно пометам словаря, эти формы предположительны или затруднительны.</div>${rows(f.uncertain)}</div>`:''}${f.absent.length?`<div class="uncertain"><h4>Отсутствующие формы</h4>${rows(f.absent)}</div>`:''}${f.missingBase?'<p class="note">Часть форм не удалось раскрыть из данных источника.</p>':''}</div>`:'<p class="meta">Для этой статьи парадигма в источнике не приведена.</p>'}</article>`}).join('')}
let serial=0;async function search(raw){let q=norm(raw),id=++serial;if(!q)return;if(!/^[а-яё-]+$/iu.test(raw.trim().normalize('NFC').replace(/[\u0300\u0301]/g,''))){results.innerHTML='<div class="state">Введите одно русское слово. Допускаются дефис и знак ударения.</div>';return}results.innerHTML='<div class="state">Ищем в словаре…</div>';try{let idx=await data('i',q),matches=idx[q]||[];if(id!==serial)return;if(!matches.length){results.innerHTML=`<div class="result-head"><div><div class="eyebrow">РЕЗУЛЬТАТ ПОИСКА</div><h2>${esc(raw)}</h2></div></div><div class="state">В словаре ничего не найдено. Проверьте написание или попробуйте другое слово.</div>`;return}let [maps,originals]=await Promise.all([Promise.all(matches.map(x=>data('d',x))),Promise.all(matches.map(x=>data('o',x)))]);if(id!==serial)return;results.innerHTML=`<div class="result-head"><div><div class="eyebrow">РЕЗУЛЬТАТ ПОИСКА</div><h2>${esc(raw)}</h2></div><p>Найдено слов: ${matches.length}</p></div>`+matches.map((m,i)=>card(m,maps[i][m],originals[i][m])).join('');results.scrollIntoView({behavior:'smooth',block:'start'})}catch(e){if(id===serial)results.innerHTML=`<div class="state">Не удалось выполнить поиск: ${esc(e.message)}. Попробуйте ещё раз.</div>`}}
$('#search').addEventListener('submit',e=>{e.preventDefault();search(input.value)});document.querySelectorAll('[data-word]').forEach(b=>b.addEventListener('click',()=>{input.value=b.dataset.word;search(input.value)}));
